const nextDisplayNumber = `-- name: NextDisplayNumber :one
SELECT (COALESCE(MAX(display_number), 0) + 1)::int4 FROM orders WHERE business_date = $1
`

// Called only under LOCK_ORDER_CREATE, so the number is unique and gap-free per business date.
func (q *Queries) NextDisplayNumber(ctx context.Context, businessDate pgtype.Date) (int32, error) {
	row := q.db.QueryRow(ctx, nextDisplayNumber, businessDate)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

const nextExpiredPendingOrder = `-- name: NextExpiredPendingOrder :one
SELECT id FROM orders
WHERE status = 'PENDING' AND expires_at <= now()
ORDER BY expires_at, id
LIMIT 1
FOR UPDATE SKIP LOCKED
`

// One order per transaction; the lock taken here is the one held while it is cancelled (F2).
func (q *Queries) NextExpiredPendingOrder(ctx context.Context) (int64, error) {
	row := q.db.QueryRow(ctx, nextExpiredPendingOrder)
	var id int64
	err := row.Scan(&id)
	return id, err
}

