const releaseReservation = `-- name: ReleaseReservation :one
UPDATE inventory_balances SET reserved = reserved - $1
WHERE product_id = $2 AND reserved >= $1
RETURNING product_id, on_hand, reserved, inventory_value_rial, last_unit_cost_rial, low_stock_alerted_at, updated_at
`

type ReleaseReservationParams struct {
	Qty       int32
	ProductID int64
}

func (q *Queries) ReleaseReservation(ctx context.Context, arg ReleaseReservationParams) (InventoryBalance, error) {
	row := q.db.QueryRow(ctx, releaseReservation, arg.Qty, arg.ProductID)
	var i InventoryBalance
	err := row.Scan(
		&i.ProductID,
		&i.OnHand,
		&i.Reserved,
		&i.InventoryValueRial,
		&i.LastUnitCostRial,
		&i.LowStockAlertedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const reserveStock = `-- name: ReserveStock :one
UPDATE inventory_balances SET reserved = reserved + $1
WHERE product_id = $2 AND on_hand - reserved >= $1
RETURNING product_id, on_hand, reserved, inventory_value_rial, last_unit_cost_rial, low_stock_alerted_at, updated_at
`

type ReserveStockParams struct {
	Qty       int32
	ProductID int64
}

// Atomic reservation: succeeds only while enough is available (no oversell).
func (q *Queries) ReserveStock(ctx context.Context, arg ReserveStockParams) (InventoryBalance, error) {
	row := q.db.QueryRow(ctx, reserveStock, arg.Qty, arg.ProductID)
	var i InventoryBalance
	err := row.Scan(
		&i.ProductID,
		&i.OnHand,
		&i.Reserved,
		&i.InventoryValueRial,
		&i.LastUnitCostRial,
		&i.LowStockAlertedAt,
		&i.UpdatedAt,
	)
	return i, err
}

